I do love a bit of FP. Here&#x27;s the canonical <i>Hello, World!</i> program.<p><pre><code>    {-# LANGUAGE OverloadedStrings #-}
    {-# LANGUAGE QuasiQuotes       #-}
    {-# LANGUAGE TemplateHaskell   #-}

    module Main where

    import Foreign.C.Types
    import Language.C.Inline qualified as C

    C.include &quot;&lt;stdio.h&gt;&quot;
    C.include &quot;&lt;stdlib.h&gt;&quot;

    main :: IO ()
    main = [C.block| void {
      system(&quot;python -c &#x27;print \&quot;Hello, World!\&quot;&#x27;&quot;);
      } |]</code></pre>
